content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体",
            "criterion": "核查签约主体的合法存续性与履约适格性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台，核查该主体是否存在未结重大诉讼、仲裁、被执行、失信、严重违法等涉法涉诉记录",
                "核对营业执照所载经营范围，确认合同项下标的（如软件采购）属于其登记的经营范围内，且无超范围经营风险",
                "逐项比对合同中列明的主体信息（联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "若合同涉及软件等技术产品采购，须核查卖方是否拥有该软件的核心知识产权（如著作权登记证书、专利证书、授权链条完整性），或明确约定知识产权归属及许可范围"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架",
            "criterion": "审查合同核心条款的完整性与结构完备性",
            "check_points": [
                "确认合同是否完整涵盖以下必备要素：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属/许可条款、产品质量保证/服务标准、交付方式与地点、验收标准与程序、完成时限（含里程碑）、违约责任（含违约金计算方式与上限）、司法管辖法院/仲裁机构、不可抗力定义与后果、廉洁承诺条款、合同变更机制、合同份数及效力说明、电子送达效力约定",
                "核实合同是否明确指定主要项目负责人，并完整载明其姓名、身份证号码、联系电话，且该信息具备可追溯性与法律约束力"
            ]
        },
        {
            "id": "C3",
            "section": "采购内容",
            "criterion": "确保标的物描述具体、唯一、可执行",
            "check_points": [
                "采购内容须清晰列明品种、规格、型号、等级、花色等技术参数；对复杂或定制化标的，应通过附件（如技术规格书、配置清单）予以固化并注明‘为本合同组成部分’",
                "附件内容须与正文引用条款严格对应，避免出现‘详见附件’但附件缺失或未命名的情形"
            ]
        },
        {
            "id": "C4",
            "section": "合同金额",
            "criterion": "保障价款条款的准确性、完整性与合规性",
            "check_points": [
                "合同金额须同时载明大小写，且二者完全一致；明确计量单位（如套、台、人天、License等）",
                "分项列明单价、数量、总价；币种须注明（如人民币/USD），涉及外币的须约定汇率适用规则",
                "总价构成须清晰（如含税价/不含税价），并注明税率及对应税目"
            ]
        },
        {
            "id": "C5",
            "section": "付款计划",
            "criterion": "强化付款节点的确定性、风险对冲性与财税合规性",
            "check_points": [
                "付款节点须以明确事件（如‘合同签订后5个工作日内’‘初验合格签署确认单后10日内’）或时间（如‘2025年6月30日前’）界定，禁用模糊表述（如‘尽快’‘及时’）",
                "预留不低于合同总额5%—10%的尾款，明确约定于免费维保期（须注明起算日及期限）届满且无质量争议后支付",
                "每笔付款均须对应约定发票类型（如增值税专用发票）、开票时点及开票信息要求"
            ]
        },
        {
            "id": "C6",
            "section": "合同期限",
            "criterion": "消除期限表述歧义，确保履行节奏可控",
            "check_points": [
                "合同期限须明确起止日期（如‘自2025年1月1日起至2026年12月31日止’），或采用‘自然日/工作日’‘自然季度/滚动季度’等无歧义计期方式",
                "若采用周期计算（如‘自生效日起满12个月’），须明确定义起始日（如‘双方签字盖章之日’）及终止日计算规则（如‘截止至第12个自然月最后一日’）"
            ]
        },
        {
            "id": "C7",
            "section": "其他基本问题",
            "criterion": "开展文本形式与逻辑一致性校验",
            "check_points": [
                "通读全文，排查错别字、标点误用、标题层级混乱（如‘第一条’后直接跳至‘第三条’）、语句成分残缺或逻辑矛盾等低级错误",
                "核验付款计划各期金额加总是否等于合同总金额；大小写金额是否完全一致",
                "比对正文与所有附件中相同条款（如验收标准、知识产权、违约责任）的表述是否严格一致，禁止存在冲突或简化省略",
                "清理招标文件、谈判纪要等前置流程中残留用语（如‘投标单位’‘响应人’‘谈判小组’），统一替换为合同语境下的规范主体称谓（如‘乙方’‘甲方’）",
                "确认合同首部‘甲方/乙方’全称、签约页‘甲方（盖章）’‘乙方（盖章）’处名称、落款签章处名称三者完全一致，不得缩写、简写或添加括号备注",
                "核查援引的法律法规名称、颁布机关、施行日期是否准确有效（如不得引用已废止的《合同法》），优先援引现行有效的《民法典》合同编及相关司法解释",
                "合同正文末尾须单独成行标注‘以下为合同签署栏’或‘以下无正文’字样，防止被篡改或增补"
            ]
        }
    ]
}
